using var transaction = await _db.Database.BeginTransactionAsync();
try {
    var order = new OrderHeader { Total = cart.Items.Sum(i => i.TotalPrice) };
    if (await _paymentService.VerifySlipAsync(dto.SlipFile)) {
        _db.OrderHeaders.Add(order);
    }
    await _db.SaveChangesAsync();
    await transaction.CommitAsync();

    // แจ้งเตือนออเดอร์ใหม่ไปที่หน้าจอห้องครัวทันทีแบบ Real-time
    await _hubContext.Clients.Group("Kitchen").SendAsync("NewOrderReceived", order);
}
catch {
    await transaction.RollbackAsync(); // ยกเลิกทั้งหมดหากมีขั้นตอนผิดพลาด
}

using var transaction = await _dbContext.Database.BeginTransactionAsync();
try {
    // ล็อกแถวสินค้าด้วย Pessimistic Concurrency ป้องกันขายเกินสต็อก
    var productStock = await _dbContext.Products.FirstOrDefaultAsync(p => p.Id == productId);
    if (productStock.Quantity >= orderQuantity) {
        productStock.Quantity -= orderQuantity; // ตัดยอดสต็อกทันที
    }
    await _dbContext.SaveChangesAsync();
    await transaction.CommitAsync();
}
catch {
    await transaction.RollbackAsync();
}

// ระบบตรวจสอบคิวหมดอายุอัตโนมัติพร้อม Retry Policy ด้วย Polly
var expiredCount = await Policy.Handle<Exception>()
    .WaitAndRetryAsync(3, attempt => TimeSpan.FromSeconds(10))
    .ExecuteAsync(async () => {
        var expiredReservations = _db.Reservations.Include(r => r.Car)
            .Where(r => r.Status == "Pending" && r.ExpiryAt < DateTime.UtcNow)
            .ToList();

        foreach (var res in expiredReservations) {
            res.Status = "Expired";
            res.Car.Status = "Available"; // ปรับสถานะรถกลับเป็นพร้อมขาย
        }
        return await _db.SaveChangesAsync();
    });

